<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Initiative extends Model { use HasUuids; protected $guarded=[]; protected function casts():array{return ['starts_on'=>'date','ends_on'=>'date','published_at'=>'datetime','audience_filters'=>'array','budget_total'=>'decimal:2','progress_percent'=>'decimal:2'];} public function owner():BelongsTo{return $this->belongsTo(User::class,'owner_user_id');} public function milestones():HasMany{return $this->hasMany(InitiativeMilestone::class);} public function partners():HasMany{return $this->hasMany(InitiativePartner::class);} public function beneficiaries():HasMany{return $this->hasMany(InitiativeBeneficiary::class);} public function budgetLines():HasMany{return $this->hasMany(InitiativeBudgetLine::class);} public function updates():HasMany{return $this->hasMany(InitiativeUpdate::class);} public function documents():HasMany{return $this->hasMany(InitiativeDocument::class);} }
